// DNR LED engine — shared by every DNR profile.
//
// ⛔ DO NOT EDIT THIS FILE BY HAND. It is written by the DNR plugin from its own copy, and
//    any change here is replaced the next time the plugin starts. It exists so the engine is
//    ONE thing that updates with the plugin, instead of ~2,950 lines copy-pasted into all 118
//    profiles — which is how 20 of them ended up a version behind, 19 of those the free ones.
//
// ⛔ DECLARATIONS ONLY. The per-device configuration (the LED counts) stays in each profile,
//    and the functions below read it through UpdateGlobalSettings at call time. SimHub gives no
//    guarantee about the order it loads the shared and embedded scripts in, so nothing here may
//    RUN at load time and depend on that configuration.
//
//DNR Embedded extensions 6.1



const f1Games = ['F12030', 'F12029', 'F12028', 'F12027', 'F12026', 'F12025', 'F12024', 'F12023', 'F12022', 'F12021'];

const ACC_DT = [1, 7, 19];
const ACC_SG = [2, 3, 4, 8, 9, 10];
const ACC_DISQ = [5, 11, 13, 15, 16, 17, 18, 20, 21];

let NM_LD_Behaviour;
let NM_DNR_Behaviour;
let TDM_LD_Behaviour;
let TDM_DNR_Behaviour;
let TDMState;
let ERSSoC;
let KERS;


// ─────────────────────────────────────────────────────────────────────────────────────────────
// DNR ONE
//
// The same seam the dashboards and the plugin use, in the LED engine: ask DNR ONE first, fall
// back to SimHub per FIELD. DNR ONE is a separate engine that normalises telemetry across sims;
// when it is not installed, or has no session, every read here answers null and everything below
// behaves exactly as it did before.
//
// ⛔⛔⛔ ADDITIVE, NEVER SUBTRACTIVE. Every use below is an OR with what the profile already read.
// DNR ONE can turn a light ON that SimHub could not, and can never turn one OFF that shows today.
// That is what makes "DNR ONE absent changes nothing" provable rather than hoped for — and it is
// checked by DnrOneEngineTests, which runs every formula in the library twice, with the seam
// present and absent, and demands identical output when it is absent.
//
// ⭐ WHY IT IS WORTH IT, concretely. Read dnr_showRedFlag below as it was: iRacing, the F1 games
// and AMS2 only. A red flag in Le Mans Ultimate could not light an LED at all, because SimHub
// exposes no red flag for it. DNR ONE reads LMU's GamePhase directly and publishes Red — so the
// same profile, unchanged, gains a red flag on a sim where one was impossible. The same goes for
// full course yellow, and for the engine warning lights, which SimHub has no equivalent of at all.
//
// ⭐ AND IT IS DEBOUNCED. Session.FlagState holds a downgrade for 30 ticks before publishing it,
// so a single-frame flicker in the game's own data cannot strobe a wheel. Every native read below
// is raw.
//
// ⚠️ null IS AMBIGUOUS ON PURPOSE. It means "no engine", "no session", "this game has no such
// field" and "not applicable right now", and they all mean the same thing to us: use SimHub.
// ─────────────────────────────────────────────────────────────────────────────────────────────

/*
  Availability is probed on a cadence rather than per read, mirroring the plugin's own 500 ms
  probe. A rig that will never have DNR ONE pays two property reads a second for the whole seam;
  without the gate it would pay one per field per container per frame.

  ⛔ THE GATE MATTERS FOR CORRECTNESS, NOT JUST COST. A DNR ONE that is installed but not
  publishing for the running game answers IsAvailable false, and its individual fields are not
  guaranteed to be anything in that state. The plugin's own reader refuses to look at them; so
  does this.
*/
let dnr_oneProbedAt = -1e9;
let dnr_oneLive = false;

function dnr_oneAvailable() {
	const now = Date.now();
	if (now - dnr_oneProbedAt < 500) return dnr_oneLive;
	dnr_oneProbedAt = now;
	dnr_oneLive = $prop('DNRLEDs.One.IsAvailable') == true;
	return dnr_oneLive;
}

/** One DNR ONE field, or null when it has no answer. */
function dnr_one(field) {
	if (!dnr_oneAvailable()) return null;
	const value = $prop('DNRLEDs.One.' + field);
	if (value === null || value === undefined) return null;
	// Blank counts as absent, exactly as the plugin's reader treats it: a rung that hands back an
	// empty string means the same as one that hands back nothing.
	if (typeof value === 'string' && value.trim() === '') return null;
	// NaN and infinity are absent rather than passed into arithmetic that would poison a bar.
	if (typeof value === 'number' && !isFinite(value)) return null;
	return value;
}

/** A DNR ONE flag. True only when DNR ONE positively says so; null and absent both read false. */
function dnr_oneFlag(field) {
	const value = dnr_one(field);
	if (value === null) return false;
	return value === true || value === 1 || value === '1'
		|| (typeof value === 'string' && value.toLowerCase() === 'true');
}

/** A DNR ONE value, or the SimHub answer beside it. */
function dnr_oneOr(field, fallback) {
	const value = dnr_one(field);
	return value === null ? fallback : value;
}

/**
 * Session.FlagState, compared without caring about case or spacing.
 *
 * ⛔ IT IS THE HIGHEST-PRIORITY FLAG, NOT A SET. Checkered beats Red beats full course yellow
 * beats Yellow beats White beats Green. So this answering false for Green during a yellow is the
 * contract working, not a gap — and it is why every caller ORs it with its own native read rather
 * than replacing it, so nothing that lights today stops lighting.
 */
function dnr_oneFlagState(...states) {
	const value = dnr_one('Session.FlagState');
	if (value === null) return false;
	const state = String(value).trim().toLowerCase();
	return states.some(s => s.toLowerCase() === state);
}

/*
  ── The car's own state ──────────────────────────────────────────────────────────────────────

  ⛔ THESE THREE REPLACE RATHER THAN ADD, and that is the right shape for them. A flag is a thing
  that is either being shown or not, so two sources can be ORed; "am I in the pit lane" has ONE
  true answer and the better source should give it. DNR ONE's bottom rung reads exactly the SimHub
  property named beside each one, so on a rig where DNR ONE has nothing better the value is
  identical — and on iRacing or LMU it comes from the game's own memory instead.

  ⭐ THE SHAPE IS PRESERVED ON PURPOSE. The profiles compare these against 1 and 0, not against
  true and false, so these return 1 and 0 rather than booleans. Changing the shape here would have
  meant editing every comparison in the library and getting one of them wrong.
*/
function dnr_inPitLane() {
	const one = dnr_one('Pit.IsInLane');
	if (one !== null) return (one === true || one === 1) ? 1 : 0;
	return $prop('IsInPitLane');
}

function dnr_pitLimiterOn() {
	const one = dnr_one('Car.PitLimiterOn');
	if (one !== null) return (one === true || one === 1) ? 1 : 0;
	return $prop('PitLimiterOn');
}

function dnr_engineMap() {
	return dnr_oneOr('Car.EngineMap', $prop('EngineMap'));
}

/*
  ⚠️ THE PROFILES ALSO READ THESE THREE DIRECTLY, AND ARE DELIBERATELY LEFT ALONE. Audited across
  the whole library: 390 inline reads of PitLimiterOn in 79 profiles, 340 of IsInPitLane in 47, and
  36 of EngineMap in 7 — the Ambient Lighting profile alone accounts for 104 of each of the first
  two. None of them come through the functions above.

  They stay as they are, on purpose:

    · The gain is small. DNR ONE's bottom rung for all three IS the SimHub property beside them, so
      it only differs on iRacing and Le Mans Ultimate, where it reads the game's own memory. SimHub
      is not wrong about the pit lane.
    · The cost is not. Many of those formulas are JSExt 0 — they do not load the shared engine at
      all, having had no reason to. Rewriting them to call an engine function means loading the
      engine for several hundred more formulas, every frame, to change a value that is usually the
      same one.
    · And it would be a bulk edit of 79 shipped profiles for that.

  The reads that MATTER all go through this engine already: every flag, the redline, the sector
  yellows and the temperature warnings. That is where DNR ONE earns its place.
*/

/*
  ── Engine warning lights ────────────────────────────────────────────────────────────────────

  ⭐⭐ NEW GROUND, NOT A BETTER VERSION OF SOMETHING. SimHub publishes no equivalent of any of
  these: they are iRacing's EngineWarnings bits and LMU's overheating flag, which nothing in the
  library could read before. A profile that wants an overheating light has had to compare a
  temperature against a number the member typed in; this is the car's own warning lamp.

  All four answer false when DNR ONE is absent, so a profile using them is safe to ship today and
  simply gains the light when DNR ONE arrives.
*/
function dnr_oneOverheating() { return dnr_oneFlag('Car.Overheating'); }

/*
  ── The redline ──────────────────────────────────────────────────────────────────────────────

  ⭐⭐⭐ THIS IS THE ONE THAT STOPS A TREADMILL. The engine carries hand-written redline tables, one
  per sim, naming hundreds of cars — and every new car iRacing releases needs a row adding by hand
  or the bar falls back to SimHub's generic redline, which is the rev LIMIT rather than the point
  the shift light should start.

  iRacing publishes the car's own shift-light blink RPM in its session data, per car, and DNR ONE
  reads it. So an unlisted car gets the number the game itself uses.

  ⛔⛔ THE HAND TABLE STILL WINS WHERE IT HAS AN ANSWER, and that ordering is deliberate rather than
  lazy. Those values are tuned — several are per gear, several deliberately differ from the game's
  own — and letting DNR ONE overrule them would change the bar on cars that already look right.
  This sits BETWEEN the table and SimHub: it can only improve a car that had no entry.
*/
function dnr_gameRedline() {
	const simhub = $prop('DataCorePlugin.CurrentGame') == 'ProjectMotorRacing'
		? $prop('CarSettings_CurrentGearRedLineRPM') //CarSettings_RedLineRPM doesn't give an absolute value for PMR
		: $prop('CarSettings_RedLineRPM');
	return dnr_oneOr('Car.RedlineRpm', simhub);
}

/*
  ── The flag box temperature warnings ────────────────────────────────────────────────────────

  The same test twenty times over: ten copies of each of these two sat inline in the SimRep MLD
  and the 8x8 Matrix Flag Box, in the Full Colour and True Dark Mode branches of every effect.

  ⭐ THE WATER ALERT GAINS THE CAR'S OWN WARNING LAMP. Until now it could only fire when SimHub
  reported a water temperature above a number the member typed in — so on a sim where SimHub
  publishes no water temperature at all, the light could never come on. DNR ONE reads iRacing's
  EngineWarnings and LMU's overheating flag directly, which is the same lamp the driver would see
  on the dashboard of the real car.

  ⛔⛔ AND THE OIL ALERT DELIBERATELY DOES NOT GET Car.LowOilPressure. It is tempting, and it is
  the wrong signal: this alert is an oil TEMPERATURE limit the member sets, and LowOilPressure is
  a PRESSURE warning. They are different faults with different causes, and quietly folding one
  into the other would change what the light means without anybody choosing that. LowOilPressure,
  LowFuelPressure, Stalled and RevLimiterActive are all available through the seam above and are
  waiting on a decision about what they should light, not on the plumbing.
*/
function dnr_waterTempAlert() {
	if (dnr_oneOverheating()) return true;
	if ($prop('TemperatureUnit') == 'Celcius') {
		return $prop('WaterTemperature') >= isnull($prop('DNRLEDs.FlagBoxTemperatureWater'), 110);
	}
	if ($prop('TemperatureUnit') == 'Fahrenheit') {
		return $prop('WaterTemperature') >= isnull($prop('DNRLEDs.FlagBoxTemperatureWater'), 230);
	}
	if ($prop('TemperatureUnit') == 'Kelvin') {
		return $prop('WaterTemperature') >= isnull($prop('DNRLEDs.FlagBoxTemperatureWater'), 383.15);
	}
}

function dnr_oilTempAlert() {
	if ($prop('OilPressure') > 0) {
		if ($prop('TemperatureUnit') == 'Celcius') {
			return $prop('OilTemperature') >= isnull($prop('DNRLEDs.FlagBoxTemperatureOil'), 120);
		}
		if ($prop('TemperatureUnit') == 'Fahrenheit') {
			return $prop('OilTemperature') >= isnull($prop('DNRLEDs.FlagBoxTemperatureOil'), 248);
		}
		if ($prop('TemperatureUnit') == 'Kelvin') {
			return $prop('OilTemperature') >= isnull($prop('DNRLEDs.FlagBoxTemperatureOil'), 393.15);
		}
	}
	return false;
}
function dnr_oneLowOilPressure() { return dnr_oneFlag('Car.LowOilPressure'); }
function dnr_oneLowFuelPressure() { return dnr_oneFlag('Car.LowFuelPressure'); }
function dnr_oneRevLimiterActive() { return dnr_oneFlag('Car.RevLimiterActive'); }
function dnr_oneStalled() { return dnr_oneFlag('Car.Stalled'); }

