/** The lights an 8x8 box has; an MLD inverts inside a centred tile rather than lighting all 150. */
const dnr_gearPanel = {
	matrix: { count: 64, invertFrom: 0, invertTo: 63 },
	mld: { count: 150, invertFrom: 0, invertTo: 149, tileCols: [7, 17], cols: 25, rows: 6 },
};

/**
 * The gear knocked out of the lit panel instead of drawn on it.
 *
 * ⛔ AN MLD INVERTS A CENTRED TILE, NOT THE WHOLE BAR. The same treatment across 25 columns is a
 *   glare strip rather than a gear; a tile the width of an 8x8 is the same picture at the same size.
 */
function dnr_gearInvert(panel, lit) {
	/*
	  ⛔⛔⛔ CENTRED FIRST. The shipped bold face is left aligned with two dead columns, and
	     complementing it lit those two solid down the right hand edge of every gear — a bright bar
	     with some dark marks beside it, rather than a number. Slim is already centred, so this
	     changes nothing there, and the DRAWN faces are never moved: only the knocked out one is.
	*/
	const cols = panel === 'mld' ? dnr_gearPanel.mld.cols : 8;
	let lo = cols, hi = -1;
	for (let i = 0; i < lit.length; i++) {
		const c = lit[i] % cols;
		if (c < lo) lo = c;
		if (c > hi) hi = c;
	}

	const nudge = hi < lo ? 0 : Math.floor((cols - (hi - lo + 1)) / 2) - lo;

	const on = {};
	for (let i = 0; i < lit.length; i++) {
		const r = Math.floor(lit[i] / cols), c = lit[i] % cols + nudge;
		if (c >= 0 && c < cols) on[r * cols + c] = true;
	}

	const out = [];
	if (panel === 'mld') {
		const p = dnr_gearPanel.mld;
		for (let r = 0; r < p.rows; r++)
			for (let c = p.tileCols[0]; c <= p.tileCols[1]; c++) {
				const i = r * p.cols + c;
				if (!on[i]) out.push(i);
			}
		return out;
	}

	for (let i = 0; i < dnr_gearPanel.matrix.count; i++) if (!on[i]) out.push(i);
	return out;
}

/**
 * The lights to turn on for a gear, in the weight this box is set to and the way round it is set to.
 *
 * ⛔ An unknown weight or an unknown gear answers with the face this panel shipped rather than
 *   nothing, so a profile from a later build asking for something this plugin has never heard of
 *   still draws a gear.
 */
function dnr_gearGlyph(panel, weight, inverted, gear) {
	const family = dnr_gearFaces[panel] || dnr_gearFaces.matrix;
	const shipped = panel === 'mld' ? family.slim : family.bold;

	// The setting arrives as the number the page stores, or as a name from a test. 1 slim, 2 bold,
	// anything else means "as this panel shipped".
	const named = weight == 1 ? 'slim' : weight == 2 ? 'bold' : weight;
	const face = family[named] || shipped;
	const text = String(gear);
	const lit = face[text] || shipped[text] || [];
	return inverted ? dnr_gearInvert(panel, lit) : lit;
}

/** The weight this box is set to: "slim", "bold", or "" for the one its panel shipped with. */
function dnr_gearWeight(box) {
	const per = $prop('DNRLEDs.FlagBoxGearWeightData') ?? [];
	const chosen = (per.length > box) ? per[box] : 0;
	return chosen == 1 ? 'slim' : chosen == 2 ? 'bold' : '';
}

/** Whether this box draws its gear knocked out of a lit panel. */
function dnr_gearInverted(box) {
	const per = $prop('DNRLEDs.FlagBoxGearInvertedData') ?? [];
	return (per.length > box) ? per[box] == true : false;
}


