/*
  ⛔⛔⛔ THE CLOCK FOR AN ANIMATION THAT MUST START AT ITS FIRST FRAME.

  SimHub restarts an animation when its container becomes ENABLED — decompiled from
  AnimationContainer: `if (isEnabled) { if (!oldStatus) { oldStatus = true; referenceTime = FrameTime; } }`.
  A looping idle logo does not care, but a SEQUENCE does: a drive through penalty that scrolls
  would start halfway across if it were played from the wall clock.

  ⭐ THE EDGE IS OBSERVABLE FROM IN HERE, AND IT DOES NOT HAVE TO BE GUESSED. Decompiled from
  MatrixContainerBase.GetResult, a container's formula runs ONLY while it is enabled:

      bool flag = (parentEnabled && IsEnabled && IsActive(data)) || ForceActive;
      … else if (flag) { multiMatrixResult = SetResultBase(data, multiMatrixResult, includedFrom); }

  So while the container is off we are not called at all, and the gap between two calls IS the
  off period. A restart is a gap far longer than the gap we have been seeing.

  ⛔ THE THRESHOLD IS LEARNED, NOT ASSUMED. SimHub's update rate is the sim's frame rate and a
  member can change it, so a fixed "more than 250 ms means off" would restart a scroll on any rig
  slower than four frames a second. This keeps a running average of the interval it is actually
  being called at and treats eight times that as the edge, with a floor so a fast rig is not
  tripped by one late frame.
*/
const dnr_animClock_states = {};
function dnr_animClock(key) {
	const now = Date.now();
	const state = dnr_animClock_states[key] ??= { startedAt: now, lastSeen: now, tick: 0 };

	const since = now - state.lastSeen;
	const edge = Math.max(250, state.tick * 8);
	if (since > edge) state.startedAt = now;            // it was off, and has just come back
	else if (since > 0) state.tick = state.tick ? (state.tick * 3 + since) / 4 : since;

	state.lastSeen = now;
	return now - state.startedAt;
}

/**
 * The frame of an animation at a given moment, as SimHub picks it.
 *
 * ⛔ EACH FRAME CARRIES ITS OWN DURATION. Walk them; never divide elapsed by the frame count.
 *   Taken from the decompiled Animation.GetFrameAt, not from the shape of the data.
 */
function dnr_animFrameAt(map, elapsedMs) {
	let total = 0;
	for (let i = 0; i < map.ms.length; i++) total += map.ms[i];
	if (total <= 0) return null;

	let t = elapsedMs % total;
	if (t < 0) t += total;

	let at = 0;
	for (let i = 0; i < map.frames.length; i++) {
		if (at + map.ms[i] > t) return map.frames[i];
		at += map.ms[i];
	}
	return null;
}

/**
 * One drawing, in the colours you hand it, painted into a flat array of cols x rows.
 *
 * This is the primitive. A profile that names its own colours calls it directly, which is how
 * the SimRep MLD's logo travels without needing a theme name.
 *
 * ⛔ Returns null when the drawing is not one we hold, so a caller can fall back rather than
 *   paint a black panel over whatever was underneath.
 */
function dnr_paintAnimation(mapId, palette, elapsedMs) {
	const map = dnr_animMaps[mapId];
	if (!map) return null;

	const frame = dnr_animFrameAt(map, elapsedMs);
	if (frame === null) return null;

	const out = new Array(map.cols * map.rows).fill(null);
	for (let i = 0; i < frame.length && i < out.length; i++) {
		const slot = dnr_animAlphabet.indexOf(frame.charAt(i));
		if (slot >= 0) out[i] = palette[slot] || null;
	}
	return out;
}

/**
 * A themed animation: the drawing this theme uses, in this theme's colours.
 *
 * ⛔ Returns null when the theme or the animation is not one we hold, so a caller can fall back
 *   rather than paint a black panel over whatever was underneath.
 */
function dnr_themedAnimation(theme, animationName, elapsedMs) {
	const owned = dnr_animThemes[theme];
	if (!owned) return null;

	let entry = null;
	for (let i = 0; i < owned.length; i++) if (owned[i].name === animationName) { entry = owned[i]; break; }
	if (!entry) return null;

	return dnr_paintAnimation(entry.map, entry.palette, elapsedMs);
}


/*
  ⭐⭐⭐ THE EFFECTS THE PROFILES SHARE.

  Measured by SHAPE rather than by byte: Ambient Lighting's 1,033 formulas are 45 distinct
  pieces of code and LED Brows' 274 are 44 — nearly all of it one function called with
  different arguments. Counting only byte-identical formulas had said the opposite, and that
  is why this was nearly not done at all.

  ⛔ EACH BODY IS THE PROFILE'S OWN CODE, UNCHANGED. The only edit is that the literals which
    differed between copies became parameters. Substituting a call's arguments back into its
    function reproduces that formula's original source character for character, and every one
    of them was checked that way before a single profile was touched.

  ⛔ THESE READ THE PROFILE'S OWN GLOBALS at call time, the way the rest of the engine does.
    Nothing here runs at load time.
*/
const dnr_sharedFormulas_marker = true;

/** Shared by 12 containers. */
function dnr_shared1(p0) {
	const dnr_totalLeds = 1;
	
	const AnimationDuration = $prop('DNRLEDs.EngineStartAnimationTotalTime') ?? 2000;
	const phase1Duration = AnimationDuration * 0.4;
	const holdDuration = AnimationDuration * 0.2;
	const phase2Duration = AnimationDuration * 0.4;
	
	let dnr_DeviceType = $prop('DNRLEDs.TDM') ?? true;
	const [phase1Colour, phase2Colour] = ['#FFFFFFFF', (UpdateGlobalColours.update(), UpdateGlobalColours.dnr_EngineStart_Hex)];
	
	if ($prop('DNRLEDs.AmbientEngineStartupAnimation')[p0] ?? true) {
		const maxSparks = Math.max(1, Math.ceil(dnr_totalLeds * 0.7));
		let animationState = globalThis.engineAnimState2;
	
		if (!animationState) {
			animationState = {
				startTime: null,
				began: false,
				centerIndex: null,
				fadeWidth: null,
				wipeMaxDistFactor: null
			};
		globalThis.engineAnimState2 = animationState;
		}
	
		if (dnr_isincreasing_maxTime(AnimationDuration, $prop('EngineStarted'), 'ENGSTART')) {
		
			const currentTime = Date.now();
	
			if (!animationState.began) {
				animationState.startTime = currentTime;
				animationState.began = true;
				animationState.centerIndex = (dnr_totalLeds - 1) / 2;
				animationState.fadeWidth = Math.max(1, Math.min(10, dnr_totalLeds * 0.1 | 0));
				animationState.wipeMaxDistFactor = dnr_totalLeds / 2 + animationState.fadeWidth;
			}
	
			const elapsedTimeTotal = currentTime - animationState.startTime;
			const EngineStartArray = new Array(dnr_totalLeds).fill('#FF000000');
	
			// PHASE 1: SPARK SHOWER
			if (elapsedTimeTotal < phase1Duration) {
				const progressPhase1 = elapsedTimeTotal / phase1Duration;
				const numSparksThisFrame = 1 + Math.floor(progressPhase1 * progressPhase1 * (maxSparks - 1));
	
				if (numSparksThisFrame > 0) {
					const sparkColour = interpolateColour(phase1Colour, phase2Colour, progressPhase1);
	
					for (let i = 0; i < numSparksThisFrame; i++) {
						const idx = Math.floor(Math.random() * dnr_totalLeds);
						EngineStartArray[idx] = sparkColour;
					}
				}
				return EngineStartArray;
			}
	
			// HOLD PHASE
			else if (elapsedTimeTotal < phase1Duration + holdDuration) {
				for (let i = 0; i < dnr_totalLeds; i++) {
					EngineStartArray[i] = phase2Colour;
				}
				return EngineStartArray;
			}
	
			// PHASE 2: CENTER WIPE-OFF
			else if (elapsedTimeTotal < AnimationDuration) {
				const progressInPhase2 = (elapsedTimeTotal - (phase1Duration + holdDuration)) / phase2Duration;
				const wipeEdgePosition = progressInPhase2 * animationState.wipeMaxDistFactor;
	
				for (let i = 0; i < dnr_totalLeds; i++) {
					const dist = Math.abs(i - animationState.centerIndex);
					let onFactor = 1;
	
					if (dist < wipeEdgePosition - animationState.fadeWidth) {
	                	onFactor = 0;
					} else if (dist < wipeEdgePosition) {
						onFactor = 1 - ((wipeEdgePosition - dist) / animationState.fadeWidth);
					}
	
				EngineStartArray[i] = interpolateColour('#FF000000', phase2Colour, Math.max(0, onFactor));
				}
			return EngineStartArray;
			}
		}
	    if (animationState && animationState.began) {
	        globalThis.engineAnimState2 = null;
	    }
	}
	return [null];
}

