/** Shared by 4 containers. */
function dnr_shared9(p0, p1) {
	UpdateGlobalSettings.update();
	const NumberOfBrowsLeds = dnr_browLeds(p0);
	const dnr_brakeLedLength = NumberOfBrowsLeds;
	
	if ((($prop('DNRLEDs.BrowsBrakeData') ?? [])[p1] ?? false) && $prop('IsInPit') == 0) {
	
		UpdateGlobalColours.update();
		const { dnr_Brake_Hex } = UpdateGlobalColours;
	
		const currentBrakePressure = dnr_brake_propertySelect();
		const ledsLit = Math.min(
			dnr_brakeLedLength,
			Math.ceil((currentBrakePressure / 100) * dnr_brakeLedLength));
	
		const halfLedsLit = ledsLit / 2;
		const halfLength = dnr_brakeLedLength / 2;
	
		let needsBlinking = false;
		let blinkOutput = null;
		let blinkThresholdLedCount = 0;
		let blinkThresholdLedCountHalf = 0;
	
		const dnr_BrakeForceBlink = $prop('DNRLEDs.BrakeForceBlink') ?? 80;
		const dnr_BrakeForceBlink2 = $prop('DNRLEDs.BrakeForceBlink2') ?? 100;
		const blinkThresholdPercent = dnr_BrakeForceBlink / 100;
	
		if (currentBrakePressure >= dnr_BrakeForceBlink && ledsLit > 0) {
			blinkThresholdLedCount = Math.floor(blinkThresholdPercent * dnr_brakeLedLength);
			blinkThresholdLedCountHalf = Math.floor(blinkThresholdPercent * halfLength);
			
			// Fix 100% blink threshold
			if (dnr_BrakeForceBlink == 100 && dnr_brakeLedLength > 0) {
				blinkThresholdLedCount = dnr_brakeLedLength - 1;
				blinkThresholdLedCountHalf = Math.ceil(halfLength) - 1;
			}
	
			needsBlinking = currentBrakePressure >= dnr_BrakeForceBlink;
			if (needsBlinking) {
				const blinkFreqSelect = currentBrakePressure >= dnr_BrakeForceBlink2
					? 75
					: 150;
				blinkOutput = Math.floor(Date.now() / blinkFreqSelect) % 2 == 0
					? dnr_Brake_Hex
					: null;
			}
		}
		const BrakeArray = new Array(dnr_brakeLedLength).fill(null);
		const applyBlink = (index) => {
			if (BrakeArray[index] !== null) BrakeArray[index] = blinkOutput;
		};
	
		// Right to Left 
		for (let i = 0; i < ledsLit; i++) {
			const pos = dnr_brakeLedLength - 1 - i;
			BrakeArray[pos] = dnr_Brake_Hex;
			if (needsBlinking && i >= blinkThresholdLedCount) applyBlink(pos);
		}
		return BrakeArray;
	}
	return [null];
}

