/** Shared by 4 containers. */
function dnr_shared14(p0, p1) {
	UpdateGlobalSettings.update();
	const NumberOfBrowsLeds = dnr_browLeds(p0);
	const dnr_totalLeds = NumberOfBrowsLeds;
	
	if ((($prop('DNRLEDs.BrowsSpottersData') ?? [])[p1] ?? true) && $prop('SpotterCarRight') == 1) {
		UpdateGlobalColours.update();
		const { dnr_Spotter_Hex } = UpdateGlobalColours;
	
		const minLEDs = 3; // Minimum LEDs that should blink
		const blinkDistance = $prop('DNRLEDs.SpotterDistance') ?? 5;
		const ledDistanceStep = 2; // Meters per LED
	
		const blinkFreq = ($prop('DataCorePlugin.CurrentGame') == 'IRacing'
						|| $prop('SpotterCarRightDistance') > blinkDistance)
							? $prop('DNRLEDs.SpotterFreqFar') ?? 300 
							: $prop('DNRLEDs.SpotterFreqClose') ?? 150;
		const blinkValue = Math.floor(Date.now() / blinkFreq) % 2;
	
		let activeLEDs = Math.max(
			minLEDs,
			dnr_totalLeds - Math.floor($prop('SpotterCarRightDistance') / ledDistanceStep));
	
		const SpotterArray = new Array(dnr_totalLeds).fill("#FF000000");
	
		if (blinkValue) {
			for (let i = dnr_totalLeds - 1; i >= dnr_totalLeds - activeLEDs; i--) {
				SpotterArray[i] = dnr_Spotter_Hex;
			}
		}
		return SpotterArray;
	}
	return [null];
}

