/** Shared by 4 containers. */
function dnr_shared25(p0, p1) {
	UpdateGlobalSettings.update();
	const NumberOfBrowsLeds = dnr_browLeds(p0);
	const dnr_lcLedLength = NumberOfBrowsLeds;
	
	if (($prop('DNRLEDs.BrowsLiftAndCoastData') ?? [])[p1] ?? true) {
	
		UpdateGlobalColours.update();
		const { dnr_LiftAndCoast_Hex } = UpdateGlobalColours;
	
		const lcvalue = $prop('GameRawData.PlayerNativeTelemetry.mLiftAndCoastProgress') ?? 0;
		const LiftAndCoastArray = new Array(dnr_lcLedLength).fill(null);
		const step = 254 / dnr_lcLedLength;
	
		if (lcvalue == 0) return LiftAndCoastArray;
		for (let i = 0; i < dnr_lcLedLength; i++) {
			if (lcvalue >= i * step) {
				const pos = dnr_lcLedLength - 1 - i;
				LiftAndCoastArray[pos] = dnr_LiftAndCoast_Hex;
			}
		}
		return LiftAndCoastArray;
	}
	return [null];
}

