function dnr_gear() {
	let gearDashboard = $prop('GameRawData.TruckValues.CurrentValues.DashboardValues.GearDashboards');

	if ($prop('DataCorePlugin.CurrentGame') !== 'ETS2' && $prop('DataCorePlugin.CurrentGame') !== 'ATS') return $prop('Gear');

	// Crawler Gears (C1, C2)
	if ($prop('GameRawData.TruckValues.ConstantsValues.MotorValues.ForwardGearCount') == 14) {
		if (gearDashboard == 1 || gearDashboard == 2) return 'C' + gearDashboard;
		if (gearDashboard >= 3) return gearDashboard - 2;
	}
	// Reverse Gears
	if (gearDashboard < 0) {
		if ($prop('GameRawData.TruckValues.ConstantsValues.MotorValues.ReverseGearCount') == 1) return 'R';
		return 'R' + -gearDashboard;
	}
	// Neutral Gear
	if (gearDashboard == 0) return 'N';
	// Return the gear number if no other conditions apply
	return gearDashboard;
};


function shouldShowFlags(dnr_flagsProperty) {
	if (!(dnr_flagsProperty)) return false;
	if ($prop('DNRLEDs.UniversalFlagsPriority') == 2 && ($prop('SpotterCarLeft') == 1 || $prop('SpotterCarRight') == 1)) return false;
	return dnr_inPitLane() == 0 || $prop('DNRLEDs.FlagsVisiblePits') != 2;
};


/*
  ⛔ THE DNR ONE TERM GOES INSIDE THE TOGGLE, ALWAYS. Every flag here is gated on the member's own
  "show this flag" setting, and a flag they have turned OFF must stay off no matter which source
  can see it. Putting the DNR ONE read outside the gate would light flags people had disabled.
*/
function dnr_showCheckeredFlag(dnr_boxOn) {
	return dnr_flagAllowed($prop('DNRLEDs.UniversalFlagsCheckered'), dnr_boxOn)
		? dnr_changed_maxTime_true (($prop('DNRLEDs.CheckeredFlagDuration') ?? 10) * 1000,
			$prop('Flag_Checkered') == 1 || dnr_oneFlagState('Checkered'), 'FlagCheckered')
		: false;
}
