function dnr_getWhiteFlagData() {
	return {
	white_flag_slow_car: (
		($prop('DataCorePlugin.CurrentGame') == 'IRacing' && $prop('SessionTypeName') != 'Lone Qualify' && $prop('IRacingExtraProperties.iRacing_SlowCarAhead') == true) ||
		($prop('DataCorePlugin.CurrentGame') == 'AssettoCorsaCompetizione' && $prop('GameRawData.Graphics.FlagsDetails.IsACC_WHITE_FLAG') == true) ||
		($prop('DataCorePlugin.CurrentGame') == 'Automobilista2' && $prop('DataCorePlugin.GameRawData.mHighestFlagColour') == 3)),
	white_flag_final_lap: (
		($prop('DataCorePlugin.CurrentGame') == 'IRacing' && $prop('Flag_White') == 1) ||
		($prop('DataCorePlugin.CurrentGame') == 'AssettoCorsaCompetizione' && $prop('GameRawData.Graphics.globalWhite') == 1) ||
		($prop('DataCorePlugin.CurrentGame') == 'Automobilista2' && $prop('DataCorePlugin.GameRawData.mHighestFlagColour') == 4) ||
		(!['IRacing', 'AssettoCorsaCompetizione', 'Automobilista2', 'EAWRC23'].includes($prop('DataCorePlugin.CurrentGame')) && $prop('RemainingLaps') == 1) ||
		/*
		  ⛔⛔ DNR ONE'S WHITE BELONGS HERE, NOT ON universalWhiteFlag, AND THE DIFFERENCE IS WHICH
		  FLAG LIGHTS. universalWhiteFlag feeds the SLOW CAR effect, gated by `&& !final_lap`; the
		  contract's White is the last-lap white, mapped from the games' own final-lap signal. Put
		  on universalWhiteFlag it would satisfy the slow-car branch while leaving the final-lap
		  term false, so a driver on their last lap would get "slow car ahead" instead of the
		  chequered-approach white. Here, it does what it says.
		*/
		dnr_oneFlagState('White')),
	universalWhiteFlag: $prop('Flag_White') == 1,
	};
}
function dnr_showWhiteFlagSlowCar(dnr_boxOn) {
	const { white_flag_slow_car, white_flag_final_lap, universalWhiteFlag } = dnr_getWhiteFlagData();
    	if (dnr_flagAllowed($prop('DNRLEDs.UniversalFlagsWhiteSlowCar'), dnr_boxOn)) {
		return (universalWhiteFlag || white_flag_slow_car) && !white_flag_final_lap;
	}
	return false;
}
function dnr_showWhiteFlagLastLap(dnr_boxOn) {
	const { white_flag_slow_car, white_flag_final_lap, universalWhiteFlag } = dnr_getWhiteFlagData();
    	if (dnr_flagAllowed($prop('DNRLEDs.UniversalFlagsWhiteFinalLap'), dnr_boxOn)) {
		if (!((universalWhiteFlag || white_flag_slow_car) && !white_flag_final_lap)) {
			return dnr_changed_maxTime_true(($prop('DNRLEDs.WhiteFlagFinalLapDuration') ?? 10) * 1000, white_flag_final_lap, 'FlagWhiteFinalLap');
		}
	}
	return false;
}
