/*
  ⭐⭐⭐ THE CLEAREST THING DNR ONE BUYS THE LEDS. Read the three native terms: iRacing, the F1
  games, and AMS2. That is the whole list — a red flag in Le Mans Ultimate, in ACC, in Assetto
  Corsa or in rFactor 2 could not light an LED, because SimHub publishes no red flag for them.

  DNR ONE reads LMU's GamePhase itself and publishes Red, so the same profile, unchanged, gains a
  red flag on a sim where one was previously impossible.
*/
function dnr_showRedFlag(dnr_boxOn) {
	return dnr_flagAllowed($prop('DNRLEDs.UniversalFlagsRed'), dnr_boxOn)
		? $prop('DataCorePlugin.CurrentGame') == 'IRacing' && $prop('GameRawData.Telemetry.SessionFlagsDetails.Isred') == true ||
			f1Games.includes($prop('DataCorePlugin.CurrentGame')) && $prop('DataCorePlugin.GameRawData.RedFlagShown') == true ||
			$prop('DataCorePlugin.CurrentGame') == 'Automobilista2' && $prop('DataCorePlugin.GameRawData.mHighestFlagColour') == 5 ||
			dnr_oneFlagState('Red')
		: false;
};

