const dnr_se_state = {};
function dnr_input (controllerId, n) {
	let s = dnr_se_state[controllerId];
	if (s === undefined) {
		const parts = String(controllerId).split(',');
		let name = null;
		if (parts.length > 1) {
			const hex = parts[1].trim().replace(/^0x0*/i, '').toUpperCase();
			if (hex.length > 0) name = 'DNRLEDs.PokornyiInputs' + hex;
		}
		s = dnr_se_state[controllerId] = { name: name, cache: null, at: 0 };
	}
	if (s.name !== null) {
		const now = Date.now();
		if (now - s.at >= 8) { s.at = now; s.cache = $prop(s.name); }
		const r = s.cache;
		if (r) {
			const len = (r.length !== undefined) ? r.length : r.Length;
			if (n >= 0 && n < len) return r[n] === true ? 1 : 0;
		}
	}
	return getcontrollerbuttonstate(controllerId, n);
}
function dnr_input_changed (maxDuration, value, key) {
	root.dnrse ??= {};
	const s = root.dnrse[key] ??= { old: null, t: null };
	if (s.old !== null && value !== s.old) s.t = Date.now();
	s.old = value;
	return s.t !== null && Date.now() - s.t <= maxDuration;
}
function dnr_input_isincreasing (maxDuration, value, key) {
	root.dnrse ??= {};
	const s = root.dnrse[key] ??= { old: value, cur: value, t: null };
	s.old = s.cur;
	s.cur = value;
	if (s.cur > s.old) s.t = Date.now();
	return s.t !== null && Date.now() - s.t <= maxDuration;
}



// Per-box flag selection. universal = the rig-wide Universal Flags switch, boxOn = this box's own
// switch (undefined when a profile passes none). A missing per-box property reads as on, so an older
// plugin, or a profile that never passes one, changes nothing.
// Whether a flag may show, for a caller that MAY be a flag box.
//
// boxOn undefined means the caller has no per-box concept at all - a wheel, a brow, an ambient
// strip - and those keep the plain Universal veto exactly as they always had. Only a caller that
// actually passes a per-box switch goes through dnr_flagOn, where a box set to pick its own flags
// may keep one Universal has switched off.
//
// This distinction is the entire fix: treating "no argument" as "independent" would have dropped
// the Universal veto on every wheel on every rig.
function dnr_flagAllowed(universal, boxOn) {
	if (boxOn === undefined) return universal ?? true;
	return dnr_flagOn(universal, boxOn);
}function dnr_flagOn(universal, boxOn) {
	// boxOn ALREADY has the Universal veto applied, per box, by the plugin. That is what lets a
	// box set to 'This box picks its own flags' keep a flag that Universal has switched off for
	// the wheel and every other device.
	// FlagBoxFlagsSourceData exists ONLY on a plugin that does that resolving. When it is absent
	// the plugin is older than this profile, the veto is still ours to apply, and behaviour stays
	// exactly as it was. An old plugin must never be read as every box being independent.
	if (($prop('DNRLEDs.FlagBoxFlagsSourceData') ?? null) === null && !(universal ?? true)) return false;
	return boxOn ?? true;
}

/* --- DNR per-brow layout (tools/rewrite-brow-reads.js) -------------------
   Brows sit end to end along the strip, in brow order. A brow with no length
   of its own falls back to the shared count, so a rig that never opens the
   per-brow page behaves exactly as it did.
   Reads the properties directly rather than through GlobalSettings, so these
   can never answer with a stale count no matter who calls them first.      */
/**
 * How many of this brow’s LEDs are LIT — the length the member chose.
 *
 * ⛔ Clamped to what the brow actually HAS. Asking for more than the brow is long used to run
 * straight into the next brow’s LEDs.
 */
function dnr_browLeds(brow) {
	const counts = $prop('DNRLEDs.BrowsLedCountData') ?? [];
	const n = (counts.length > brow) ? counts[brow] : 0;
	const want = n > 0 ? n : ($prop('DNRLEDs.BrowsNumberOfLeds') ?? 9);
	const span = dnr_browSpanRaw(brow);
	return span > 0 ? Math.min(want, span) : want;
}

/**
 * The measured span, or 0 when nothing measured this brow. Never falls back — see dnr_browSpan.
 *
 * ⛔⛔⛔ THIS DEVICE’S OWN NUMBER FIRST. A rig can carry brows on more than one device — a GRID
 * pair and a DDU with a built-in pair — and both are "brow 1 and brow 2", so the published array can
 * only ever hold ONE of their lengths. The profile installed on a device is stamped with that
 * device’s own answer, which is the only one that can be right for the strip it is drawing on.
 *
 * ⭐ Guarded with typeof, because this engine is shared by every profile and only the brow ones
 * declare it. An undeclared name is a ReferenceError, not undefined.
 */
function dnr_browSpanRaw(brow) {
	if (typeof BrowsLedsPerBrow !== 'undefined' && BrowsLedsPerBrow > 0) return BrowsLedsPerBrow;

	const spans = $prop('DNRLEDs.BrowsLedSpanData') ?? [];
	const n = (spans.length > brow) ? spans[brow] : 0;
	return n > 0 ? n : 0;
}

/**
 * How many LEDs this brow physically OCCUPIES on the strip.
 *
 * ⛔⛔⛔ NOT THE SAME NUMBER AS dnr_browLeds, AND TREATING THEM AS ONE PUT BOTH BROWS INSIDE ONE.
 * Every brow started where the last one’s LIT length ended, so a pair of nine-LED brows asked to
 * light five drew LEDs 0-4 and 5-9 — ten in a row on the first brow, nothing on the second, and the
 * whole strip eight LEDs short. Daniel, 2026-09-10: <i>"its not recognising each brow is 9 leds long
 * and if i pick length of 5, it should be 5 per brow, not 10 in a row together"</i>. The lit length
 * says how much to light; only the SPAN may say where the next brow begins.
 *
 * ⭐ Falls back to the lit length, which is exactly what every brow did before, so a rig whose
 * device reports no LED count behaves precisely as it does today.
 */
function dnr_browSpan(brow) {
	const span = dnr_browSpanRaw(brow);
	return span > 0 ? span : dnr_browLeds(brow);
}

/** Where this brow starts on the strip. ⛔ Strides by SPAN, never by the lit length. */
function dnr_browStart(brow) {
	let start = 0;
	for (let i = 0; i < brow; i++) start += dnr_browSpan(i);
	return start;
}

/** How many brows are fitted. */
function dnr_browCount() {
	return $prop('DNRLEDs.BrowsCount') ?? 2;
}

/**
 * Every fitted brow's LEDs added up.
 *
 * ⛔ NOT "the shared count times the number of brows". Brows are sized individually — that is the
 * whole point of BrowsLedCountData — so a rig with a nine-LED brow beside a twelve-LED one has a
 * span of twenty-one, and the product gives eighteen or twenty-four depending on which brow the
 * shared fallback happens to describe. Anything drawing across the whole set has to add them up.
 */
function dnr_browTotalLeds() {
	return dnr_browStart(dnr_browCount());
}

/**
 * Has the member flipped this brow?
 *
 * ⛔ IT MATTERS ONLY TO THINGS THAT HAVE A DIRECTION. The generated idle animations are symmetric
 * about their centre, so mirroring one is invisible; a CUSTOM idle strip is a sequence the member
 * chose, left to right, and on a flipped brow it has to be drawn backwards. The old right-hand
 * brow profile mirrored its whole idle for exactly this reason.
 */
function dnr_browFlip(brow) {
	const flips = $prop('DNRLEDs.BrowsFlipData') ?? [];
	return (flips.length > brow) ? flips[brow] == true : false;
}

/** Reverse the slice of a whole-strip array that belongs to each flipped brow, in place. */
function dnr_browApplyFlips(strip) {
	if (!strip || !strip.length) return strip;
	const count = dnr_browCount();
	let at = 0;
	for (let brow = 0; brow < count; brow++) {
		// ⛔ MIRRORED WITHIN THE BROW’S PHYSICAL SPAN, not within its lit part. A flipped brow
		//   lighting five of nine lights the LAST five, which is the whole point of flipping it.
		const leds = dnr_browSpan(brow);
		if (dnr_browFlip(brow)) {
			for (let i = 0; i < Math.floor(leds / 2); i++) {
				const a = at + i, z = at + leds - 1 - i;
				if (z >= strip.length) break;
				const held = strip[a]; strip[a] = strip[z]; strip[z] = held;
			}
		}
		at += leds;
	}
	return strip;
}
